function doubleBooked(bookings) {
  let i = 0
  while (i < bookings.length) {
    const home = bookings[i] - 1
    if (bookings[home] !== bookings[i]) [bookings[i], bookings[home]] = [bookings[home], bookings[i]]
    else i++
  }
  const repeats = []
  for (let k = 0; k < bookings.length; k++) if (bookings[k] !== k + 1) repeats.push(bookings[k])
  return repeats.sort((a, b) => a - b)
}

