def double_booked(bookings):
    i = 0
    while i < len(bookings):
        home = bookings[i] - 1
        if bookings[home] != bookings[i]:
            bookings[i], bookings[home] = bookings[home], bookings[i]
        else:
            i += 1
    repeats = [bookings[k] for k in range(len(bookings)) if bookings[k] != k + 1]
    return sorted(repeats)
